const NIL:u16=u16::MAX;const ACTIVE:u64=1<<63;
#[derive(Clone,Copy)]struct Slot{meta:u64,token:i64}
#[derive(Default)]struct Counts{arrivals:u64,first:u64,updates:u64,queued:u64,drained:u64,spilled:u64,flushes:u64,initial:u64,adds:u64,max_ready:usize,max_queue:usize,promote_checks:u64,hist:BTreeMap<usize,u64>}
struct Engine{cap:usize,occupied:Vec<bool>,busy:Vec<bool>,heads:Vec<u16>,slots:Vec<Slot>,free:u16,queued:usize,affine:Vec<i128>,projective:Vec<i128>,projective_seen:Vec<bool>,expected:Vec<i128>,ready:Vec<(usize,i64)>,c:Counts}
fn next(meta:u64)->u16{(meta>>32)as u16}
impl Engine{
 fn new(n:usize,cap:usize)->Self{assert!(n>0&&n<=u32::MAX as usize&&cap>=8&&cap<=u16::MAX as usize);assert_eq!(std::mem::size_of::<Slot>(),16);Self{cap,occupied:vec![false;n],busy:vec![false;n],heads:vec![NIL;n],slots:Vec::with_capacity(cap-1),free:NIL,queued:0,affine:vec![0;n],projective:vec![0;n],projective_seen:vec![false;n],expected:vec![0;n],ready:Vec::with_capacity(cap),c:Counts::default()}}
 fn add(&mut self,b:usize,t:i64){assert!(!self.busy[b]);if !self.occupied[b]{self.occupied[b]=true;self.affine[b]=t as i128;self.c.first+=1;}else{self.busy[b]=true;self.ready.push((b,t));self.c.max_ready=self.c.max_ready.max(self.ready.len());assert!(self.ready.len()<=self.cap);}}
 fn enqueue(&mut self,b:usize,t:i64){let ix=if self.free==NIL{let ix=u16::try_from(self.slots.len()).unwrap();assert_ne!(ix,NIL);self.slots.push(Slot{meta:0,token:0});ix}else{let ix=self.free;self.free=next(self.slots[ix as usize].meta);ix};self.slots[ix as usize]=Slot{meta:ACTIVE|b as u64|((self.heads[b]as u64)<<32),token:t};self.heads[b]=ix;self.queued+=1;self.c.queued+=1;self.c.max_queue=self.c.max_queue.max(self.queued);assert!(self.slots.len()<self.cap);}
 fn pop(&mut self,b:usize)->i64{let ix=self.heads[b];assert_ne!(ix,NIL);let s=self.slots[ix as usize];assert!(s.meta&ACTIVE!=0);assert_eq!(s.meta as u32 as usize,b);self.heads[b]=next(s.meta);self.slots[ix as usize].meta=(self.free as u64)<<32;self.free=ix;self.queued-=1;self.c.drained+=1;s.token}
 fn execute(&mut self,promote:bool){let n=self.ready.len();if n==0{return}*self.c.hist.entry(n).or_default()+=1;for j in 0..n{let(b,t)=self.ready[j];assert!(self.busy[b]);self.busy[b]=false;self.affine[b]+=t as i128;self.c.updates+=1;}let mut keep=0;if promote{for j in 0..n{let b=self.ready[j].0;self.c.promote_checks+=1;if self.heads[b]!=NIL{let t=self.pop(b);assert!(!self.busy[b]);self.busy[b]=true;self.ready[keep]=(b,t);keep+=1;}}}self.ready.truncate(keep);}
 fn flush(&mut self){if self.queued==0{return}self.c.flushes+=1;let mut n=0;for s in &self.slots{if s.meta&ACTIVE==0{continue}let b=s.meta as u32 as usize;self.heads[b]=NIL;self.projective[b]+=s.token as i128;self.c.spilled+=1;n+=1;if self.projective_seen[b]{self.c.adds+=1;}else{self.projective_seen[b]=true;self.c.initial+=1;}}assert_eq!(n,self.queued);self.queued=0;self.free=NIL;self.slots.clear();}
 fn feed(&mut self,b:usize,t:i64){assert!(b<self.affine.len());self.c.arrivals+=1;self.expected[b]+=t as i128;if self.busy[b]{self.enqueue(b,t);if self.queued==self.cap-1{self.flush();}return}self.add(b,t);if self.ready.len()==self.cap{self.execute(true);}}
 fn finish(mut self)->(Vec<i128>,Value){self.execute(false);self.flush();assert!(self.busy.iter().all(|v|!*v));assert!(self.heads.iter().all(|v|*v==NIL));for i in 0..self.affine.len(){self.affine[i]+=self.projective[i];assert_eq!(self.affine[i],self.expected[i]);}let c=self.c;assert_eq!(c.arrivals,c.first+c.updates+c.spilled);assert_eq!(c.queued,c.drained+c.spilled);assert_eq!(c.spilled,c.initial+c.adds);assert_eq!(c.updates,c.hist.iter().map(|(n,c)|*n as u64*c).sum::<u64>());let mut bytes=Vec::new();for v in &self.affine{bytes.extend(v.to_le_bytes());}let digest=format!("{:x}",Sha256::digest(bytes));let stages=c.hist.values().sum::<u64>();let groups=c.hist.iter().map(|(n,c)|(*n/8)as u64*c).sum::<u64>();let tails=c.hist.iter().map(|(n,c)|(*n%8)as u64*c).sum::<u64>();let v=json!({"arrivals":c.arrivals,"first_writes":c.first,"ordinary_affine_updates":c.updates,"queue_arrivals":c.queued,"queue_drained":c.drained,"projective_arrivals":c.spilled,"projective_initializations":c.initial,"projective_accumulator_adds":c.adds,"queue_flushes":c.flushes,"batch_histogram":c.hist,"inverse_stages_model":stages,"vector_groups":groups,"scalar_tail_pairs":tails,"max_ready":c.max_ready,"max_queue":c.max_queue,"promotion_head_checks":c.promote_checks,"bucket_slots":self.occupied.len(),"additional_head_payload_bytes":2*self.occupied.len(),"slot_bytes":std::mem::size_of::<Slot>(),"slot_capacity":self.cap-1,"signed_bucket_sums_sha256":digest,"integer_group_conservation":true});(self.affine,v)}
}
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn digit(s:[u64;4],start:usize,width:usize)->i16{if start==0{let v=s[0]&((1u64<<width)-1);return(v as i64-((v>>(width-1))<<width)as i64)as i16;}let off=start-1;let word=off/64;let sh=off%64;let mut v=s[word]>>sh;if sh+width+1>64&&word<3{v|=s[word+1]<<(64-sh);}v&=(1u64<<(width+1))-1;(((v+1)>>1)as i64-((v>>width)<<width)as i64)as i16}
fn main(){assert!(!Path::new(R).join("analysis.json").exists());for(p,h)in read(format!("{R}/pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let old=read("/home/ubuntu/src/zopro-perf-work/g1-two-pending-count176/analysis.json");let binding=read("/home/ubuntu/src/zopro-perf-work/g1-tagged-phi-review176/analysis.json");assert_eq!(hash(CACHE),binding["cache"]["sha256"]);let bytes=fs::read(CACHE).unwrap();assert_eq!(&bytes[..8],b"TAGPHI01");let get=|at|u64::from_le_bytes(bytes[at..at+8].try_into().unwrap());let(nk,nh)=(get(8)as usize,get(16)as usize);assert_eq!((nk,nh),(30529,30922));assert_eq!(bytes.len(),64+65*(nk+nh));let mut windows=vec![];let mut totals=BTreeMap::<String,u64>::new();let keys=["arrivals","first_writes","ordinary_affine_updates","queue_arrivals","queue_drained","projective_arrivals","projective_initializations","projective_accumulator_adds","queue_flushes","inverse_stages_model","vector_groups","scalar_tail_pairs","bucket_slots","additional_head_payload_bytes","promotion_head_checks"];
 for w in 0..20{let start=w*255/20;let width=(w+1)*255/20-start;let half=1usize<<(width-1);let cap=if width==12{200}else{352};let mut e=Engine::new(half,cap);for i in 0..nk+nh{let at=64+65*i;assert!(bytes[at+64]<=1);let s=core::array::from_fn(|j|get(at+8*j));let d=digit(s,start,width);if d!=0&&bytes[at+64]==0{e.feed(d.unsigned_abs()as usize-1,(i+1)as i64*if d<0{-1}else{1});}}let(out,c)=e.finish();let weighted=out.iter().enumerate().map(|(b,v)|(b as i128+1)*v).sum::<i128>();for key in keys{*totals.entry(key.into()).or_default()+=c[key].as_u64().unwrap();}windows.push(json!({"window":w,"start":start,"width":width,"ready_capacity":cap,"counts":c,"weighted_signed_token_sum":weighted.to_string()}));}
 let b=&old["baseline"];let joins=totals["ordinary_affine_updates"]+totals["projective_arrivals"];let checks=BTreeMap::from([("generic_join_and_arrival_conservation",totals["arrivals"]==1170733&&joins==1100052&&totals["first_writes"]==70681),("strictly_fewer_projective_arrivals",totals["projective_arrivals"]<b["projective_arrivals"].as_u64().unwrap()),("strictly_fewer_projective_accumulator_adds",totals["projective_accumulator_adds"]<b["projective_accumulator_adds"].as_u64().unwrap()),("no_more_projective_normalization_buckets",totals["projective_initializations"]<=b["projective_initializations"].as_u64().unwrap())]);let selected=checks.values().all(|v|*v);let v=json!({"candidate_windows":windows,"candidate_totals":totals,"original_saved_totals":b,"necessary_checks":checks,"native_implementation_selected_by_counts":selected,"performance_measured":false,"adopted":false,"new_SDK_requests":0,"new_Gnark_exports":0,"canonical_proofs":43083,"production_unchanged":true,"goal_active":true,"goal_complete":false,"targets_met":0,"cache_sha256":hash(CACHE),"model_scope":"Generic noncancelling ordinary occupancy with exact signed-integer token sums; curve exceptions, native layout/admission/resources/concurrency and speed unqualified"});fs::write(format!("{R}/analysis.json"),serde_json::to_vec_pretty(&v).unwrap()).unwrap();println!("BUCKET_READY_COUNT stages={} projective={} normalization={} heads={} selected={selected};notlatency",totals["inverse_stages_model"],totals["projective_arrivals"],totals["projective_initializations"],totals["additional_head_payload_bytes"]);}
#[cfg(test)]mod tests{use super::*;#[test]fn bounded_slots_outputs_and_reuse(){let mut cases=0;let mut reused=0;for n in[1usize,8,31,512]{for cap in[8usize,16,24,200,352]{for pattern in 0..6{let mut e=Engine::new(n,cap);let mut want=vec![0i128;n];for i in 0..4097{let b=match pattern{0=>0,1=>i%n,2=>(i/3)%n,3=>(i*17+i/7)%n,4=>(i*i+3*i)%n,_=>if i%7==0{i%n}else{0}};let t=(i+1)as i64*if i%3==0{-1}else{1};want[b]+=t as i128;e.feed(b,t);if e.free!=NIL{reused+=1;}assert!(e.ready.len()<=cap&&e.queued<cap&&e.slots.len()<cap);}let(out,c)=e.finish();assert_eq!(out,want);assert_eq!(c["slot_bytes"],16);cases+=1;}}}assert_eq!(cases,120);assert!(reused>0);println!("BUCKET_READY_STATE_CASES={cases};free_list_observed={reused}");}#[test]fn directed_promotions_are_distinct_and_preserve_lifo(){let mut e=Engine::new(16,16);for b in 0..16{e.feed(b,1);e.feed(b,2);if b<7{e.feed(b,3);e.feed(b,4);}}assert_eq!(e.ready.len(),7);assert_eq!(e.queued,7);assert!(e.ready.iter().all(|(_,t)|*t==4));for(b,_)in &e.ready{assert!(e.busy[*b]);}let(out,_)=e.finish();assert_eq!(out,vec![10,10,10,10,10,10,10,3,3,3,3,3,3,3,3,3]);println!("BUCKET_READY_DIRECT_PROMOTION_PASS");}#[test]fn bounds_and_empty(){let e=Engine::new(1,65535);assert_eq!(e.finish().0,vec![0]);for cap in[0,7,65536]{assert!(std::panic::catch_unwind(||Engine::new(1,cap)).is_err());}println!("BUCKET_READY_BOUNDARY_PASS");}}
